//! End-to-end coverage of `static/composition`, driven through the **real
//! binary** over a hermetic on-disk fixture.
//!
//! The contract under test (see `site/analyzers/composition.md`):
//!
//! * every walked file is classified — vendored and generated files are
//!   counted by default (only `--languages` narrows the walk);
//! * files that match no rule land in `other`, never in `source`;
//! * `--per-file` entries carry the file's category and language;
//! * the output is deterministic.

mod common;

use std::path::Path;

use serde_json::Value;

/// Path to the freshly built `codefang` binary under test.
const BIN: &str = env!("CARGO_BIN_EXE_codefang");

/// Section title of the composition report.
const SECTION_TITLE: &str = "COMPOSITION";

/// Info-only score label.
const SCORE_INFO: &str = "Info";

/// Tolerance for the distribution-sum assertion.
const SUM_TOLERANCE: f64 = 1e-9;

/// The fixture: one file per category, plus extra documentation,
/// configuration and source files so the percentages are not all equal
/// (`schema.sql` is source: enry lists `.sql` under PL/SQL first).
fn fixture() -> tempfile::TempDir {
    let dir = tempfile::tempdir().expect("tempdir");
    let files: &[(&str, &[u8])] = &[
        (".editorconfig", b"[*]\nindent_style = tab\n"),
        ("README.md", b"# Title\n"),
        ("config.yaml", b"key: value\n"),
        ("data.bin", b"\x00\x01\x02\xff\x00\x00\x00"),
        ("docs/guide.md", b"# Guide\n"),
        ("empty.go", b""),
        (
            "gen/thing.pb.go",
            b"// Code generated by protoc-gen-go. DO NOT EDIT.\npackage gen\n",
        ),
        ("logo.png", b""),
        ("main.go", b"package main\n\nfunc main() {}\n"),
        ("schema.sql", b"SELECT 1;\n"),
        ("settings.json", b"{\"a\":1}"),
        ("vendor/x/y.go", b"package x\n"),
        ("data.xyz", b"hello world\n"),
    ];
    for (rel, content) in files {
        let path = dir.path().join(rel);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).expect("mkdir");
        }
        std::fs::write(path, content).expect("write fixture");
    }
    dir
}

/// Runs `codefang run -a static/composition <extra> <path>` with a pinned
/// environment and returns the raw stdout bytes.
fn run_composition(path: &Path, extra: &[&str]) -> Vec<u8> {
    let out = common::command(BIN)
        .arg("run")
        .args(["-a", "static/composition"])
        .args(extra)
        .arg(path)
        .env("TZ", "UTC")
        .env("NO_COLOR", "1")
        .env("LANG", "C")
        .env("LC_ALL", "C")
        .output()
        .expect("run the codefang binary");
    assert!(
        out.status.success(),
        "run failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    out.stdout
}

/// The single composition section of a `--format json` run.
fn composition_section(path: &Path, extra: &[&str]) -> Value {
    let stdout = run_composition(path, &[&["--format", "json"], extra].concat());
    let report: Value = serde_json::from_slice(&stdout).expect("valid JSON report");
    let sections = report["sections"].as_array().expect("sections array");
    assert_eq!(sections.len(), 1, "one composition section expected");
    assert_eq!(sections[0]["title"], SECTION_TITLE);
    sections[0].clone()
}

/// Looks up a `metrics[].value` by label.
fn metric(entry: &Value, label: &str) -> String {
    entry["metrics"]
        .as_array()
        .expect("metrics array")
        .iter()
        .find(|m| m["label"] == label)
        .unwrap_or_else(|| panic!("metric {label} missing in {entry}"))["value"]
        .as_str()
        .expect("metric value string")
        .to_string()
}

/// `(label, count)` of every distribution row, in emitted order.
fn distribution(entry: &Value) -> Vec<(String, i64)> {
    entry["distribution"]
        .as_array()
        .map(|rows| {
            rows.iter()
                .map(|d| {
                    (
                        d["label"].as_str().expect("label").to_string(),
                        d["count"].as_i64().expect("count"),
                    )
                })
                .collect()
        })
        .unwrap_or_default()
}

/// Every category is counted by default, vendor and generated included, and
/// an unknown extension lands in `other` rather than `source`.
#[test]
fn default_run_counts_every_category_including_vendor_and_generated() {
    let dir = fixture();
    let section = composition_section(dir.path(), &[]);

    assert_eq!(metric(&section, "Total Files"), "13");
    assert_eq!(metric(&section, "Source Files"), "3");
    assert_eq!(metric(&section, "Source %"), "23.1%");
    assert_eq!(section["status"], "File composition analysis completed");
    assert_eq!(section["score_label"], SCORE_INFO);

    assert_eq!(
        distribution(&section),
        vec![
            ("source".to_string(), 3),
            ("documentation".to_string(), 2),
            ("configuration".to_string(), 2),
            ("vendor".to_string(), 1),
            ("generated".to_string(), 1),
            ("dotfile".to_string(), 1),
            ("image".to_string(), 1),
            ("binary".to_string(), 1),
            ("other".to_string(), 1),
        ]
    );
}

/// The distribution fractions of one run sum to 1 (they are `0..1` shares).
#[test]
fn distribution_fractions_sum_to_one() {
    let dir = fixture();
    let section = composition_section(dir.path(), &[]);
    let sum: f64 = section["distribution"]
        .as_array()
        .expect("distribution")
        .iter()
        .map(|d| d["percent"].as_f64().expect("percent"))
        .sum();
    assert!((sum - 1.0).abs() < SUM_TOLERANCE, "fractions sum to {sum}");
}

/// `--per-file` entries carry each file's category and language.
#[test]
fn per_file_entries_carry_the_category() {
    let dir = fixture();
    let section = composition_section(dir.path(), &["--per-file"]);

    let files = section["files"].as_array().expect("files array");
    let by_path = |rel: &str| -> &Value {
        files
            .iter()
            .find(|f| f["file_path"] == rel)
            .unwrap_or_else(|| panic!("no entry for {rel}"))
    };

    let vendored = by_path("vendor/x/y.go");
    assert_eq!(vendored["status"], "Classified as vendor");
    assert_eq!(vendored["score_label"], SCORE_INFO);
    assert_eq!(metric(vendored, "Total Files"), "1");
    assert_eq!(metric(vendored, "Vendor Files"), "1");
    assert_eq!(metric(vendored, "Vendor %"), "100.0%");
    assert_eq!(metric(vendored, "Language"), "Go");
    assert_eq!(distribution(vendored), vec![("vendor".to_string(), 1)]);

    let generated = by_path("gen/thing.pb.go");
    assert_eq!(generated["status"], "Classified as generated");

    let docs = by_path("docs/guide.md");
    assert_eq!(docs["status"], "Classified as documentation");
    assert_eq!(metric(docs, "Language"), "Markdown");

    let other = by_path("data.xyz");
    assert_eq!(other["status"], "Classified as other");
    assert_eq!(metric(other, "Language"), "unknown");

    let paths: Vec<&str> = files
        .iter()
        .map(|f| f["file_path"].as_str().expect("file_path"))
        .collect();
    let mut sorted = paths.clone();
    sorted.sort_unstable();
    assert_eq!(paths, sorted, "entries follow the lexical walk order");
    assert_eq!(paths.len(), 13);
}

/// Without `--per-file` the section carries no `files` key.
#[test]
fn no_per_file_flag_omits_files() {
    let dir = fixture();
    let section = composition_section(dir.path(), &[]);
    assert!(section.get("files").is_none(), "files must be omitted");
}

/// `--languages` is the only filter: it narrows the walk to the selected
/// language's files, which are still classified in every category.
#[test]
fn languages_flag_narrows_the_walk() {
    let dir = fixture();
    let section = composition_section(dir.path(), &["--languages", "go"]);

    assert_eq!(metric(&section, "Total Files"), "4");
    assert_eq!(
        distribution(&section),
        vec![
            ("source".to_string(), 2),
            ("vendor".to_string(), 1),
            ("generated".to_string(), 1),
        ]
    );
}

/// An empty tree reports zero files with the empty status and no
/// distribution.
#[test]
fn empty_tree_reports_no_files() {
    let dir = tempfile::tempdir().expect("tempdir");
    let section = composition_section(dir.path(), &[]);
    assert_eq!(metric(&section, "Total Files"), "0");
    assert_eq!(metric(&section, "Source %"), "0.0%");
    assert_eq!(section["status"], "No files analyzed");
    assert!(section.get("distribution").is_none());
    assert_eq!(section["issues"].as_array().map(Vec::len), Some(0));
}

/// The YAML breakdown lists every category, `other` included.
#[test]
fn yaml_breakdown_lists_every_category() {
    let dir = fixture();
    let yaml = String::from_utf8(run_composition(dir.path(), &["--format", "yaml"])).unwrap();
    assert!(yaml.contains("total_files: 13\n"), "{yaml}");
    for line in [
        "    vendor: 1\n",
        "    generated: 1\n",
        "    other: 1\n",
        "    source: 3\n",
    ] {
        assert!(yaml.contains(line), "missing {line:?} in:\n{yaml}");
    }
}

/// Two runs over the same tree produce identical bytes in every format.
#[test]
fn two_runs_are_byte_identical() {
    let dir = fixture();
    for format in ["json", "yaml", "text", "compact"] {
        let first = run_composition(dir.path(), &["--format", format]);
        let second = run_composition(dir.path(), &["--format", format]);
        assert_eq!(first, second, "--format {format} must be deterministic");
    }
}
